"""Generate images and publish only generated bytes to the configured image store."""
import asyncio
import base64
import binascii
import os
import re
from urllib.parse import urlsplit, unquote

import httpx

IMAGE_TOOL = {
    'type': 'function', 'name': 'generate_image',
    'description': '사용자가 실제 그림·일러스트·이미지 생성을 요청할 때 사용한다. ASCII나 설명으로 대체하지 않는다. 이미지 검색, 그리는 방법 설명, 명시적인 ASCII 요청에는 사용하지 않는다. 스타일이 없으면 적절히 선택한다. 입력 사진 편집은 지원하지 않는다.',
    'strict': True,
    'parameters': {'type': 'object', 'properties': {
        'prompt': {'type': 'string', 'description': '사용자 요청과 대화 맥락을 반영한 구체적인 이미지 생성 설명. 비밀키나 사용자 식별자는 포함하지 않는다.'}
    }, 'required': ['prompt'], 'additionalProperties': False},
}


class ImageService:
    def __init__(self):
        self.key = os.environ.get('OPENAI_API_KEY', '').strip()
        self.model = os.environ.get('OPENAI_IMAGE_MODEL', 'gpt-image-1.5')
        self.store = urlsplit(os.environ.get('CLOUDINARY_URL', ''))
        self.slots = asyncio.Semaphore(2)

    def configured(self):
        return (self.store.scheme == 'cloudinary' and self.store.username
                and self.store.password and self.store.hostname
                and re.fullmatch(r'[a-zA-Z0-9_-]+', self.store.hostname))

    async def generate(self, client, prompt):
        if not self.configured():
            return '이미지 저장소 연결을 준비 중이에요. 운영자가 CLOUDINARY_URL을 설정하면 실제 그림을 보내드릴 수 있어요.'
        if not isinstance(prompt, str) or not prompt.strip() or len(prompt) > 12000:
            return '그릴 내용을 짧게 다시 알려주세요.'
        if self.slots.locked():
            return '현재 다른 그림을 생성 중이에요. 잠시 후 다시 요청해 주세요.'
        async with self.slots:
            try:
                async with asyncio.timeout(200):
                    response = await client.post('https://api.openai.com/v1/images/generations',
                        headers={'Authorization': f'Bearer {self.key}'},
                        json={'model': self.model, 'prompt': prompt, 'n': 1,
                              'size': '1024x1024', 'quality': 'medium',
                              'output_format': 'jpeg'}, timeout=170)
                    print(f'Image generation HTTP {response.status_code}', flush=True)
                    if response.status_code in (401, 403):
                        return '이미지 모델 접근 권한이 없어요. 운영자는 OpenAI API 권한과 조직 인증 상태를 확인해 주세요.'
                    if response.status_code == 429:
                        return '이미지 생성 사용 한도 또는 잔액을 확인해야 해요. 잠시 후 다시 시도해 주세요.'
                    if response.status_code == 400:
                        return '이 요청으로 그림을 만들지 못했어요. 요청 내용을 바꿔 다시 시도해 주세요.'
                    response.raise_for_status()
                    encoded = response.json()['data'][0]['b64_json']
                    if len(encoded) > 20_000_000:
                        raise ValueError('Image too large')
                    raw = base64.b64decode(encoded, validate=True)
                    if not raw.startswith(b'\xff\xd8\xff'):
                        raise ValueError('Invalid JPEG')
                    upload = await client.post(
                        f'https://api.cloudinary.com/v1_1/{self.store.hostname}/image/upload',
                        auth=(unquote(self.store.username), unquote(self.store.password)),
                        files={'file': ('generated.jpg', raw, 'image/jpeg')},
                        data={'use_filename': 'false', 'overwrite': 'false'}, timeout=25)
                    print(f'Image upload HTTP {upload.status_code}', flush=True)
                    if not upload.is_success:
                        return '그림은 생성했지만 저장소에 업로드하지 못했어요. 운영자는 Cloudinary 설정과 사용 한도를 확인해 주세요.'
                    url = upload.json()['secure_url']
                    parsed = urlsplit(url)
                    if parsed.scheme != 'https' or parsed.hostname != 'res.cloudinary.com':
                        raise ValueError('Invalid delivery URL')
                    return {'simpleImage': {'imageUrl': url, 'altText': '요청하신 AI 생성 그림'}}
            except (TimeoutError, httpx.TimeoutException):
                return '그림 생성 시간이 길어 요청을 종료했어요. 잠시 후 다시 요청해 주세요.'
            except (httpx.HTTPError, ValueError, KeyError, IndexError, TypeError, binascii.Error):
                return '이미지 생성 또는 저장 중 오류가 발생했어요. 잠시 후 다시 시도해 주세요.'
